import numpy as np

W1 = W['W1']
norms = np.zeros((10, 10, 5))
for r in range(10):
    for c in range(10):
        for ch in range(5):
            idx = (r * 10 + c) * 5 + ch
            norms[r, c, ch] = np.linalg.norm(W1[idx, :])

rows = np.arange(10)
cols = np.arange(10)
for ch in range(5):
    total = norms[:, :, ch].sum()
    if total > 0:
        row_com = (norms[:, :, ch].sum(axis=1) * rows).sum() / total
        col_com = (norms[:, :, ch].sum(axis=0) * cols).sum() / total
        max_idx = np.unravel_index(np.argmax(norms[:, :, ch]), norms[:, :, ch].shape)
        print(f"Channel {ch}: center of mass (row, col) = ({row_com:.2f}, {col_com:.2f}), "
              f"total norm = {total:.2f}, max = {norms[max_idx[0], max_idx[1], ch]:.2f} at {max_idx}")
    else:
        print(f"Channel {ch}: zero weights")
